import ar.com.fdvs.dj.domain.builders.FastReportBuilder;
import ar.com.fdvs.dj.test.TestRepositoryProducts;
import ar.com.fdvs.dj.test.util.MyUtils;
import net.sf.jasperreports.engine.JasperFillManager;
import net.sf.jasperreports.engine.JasperPrint;
import net.sf.jasperreports.engine.data.JRBeanCollectionDataSource;
import net.sf.jasperreports.engine.export.JRPdfExporter;

public class SimpleExample {

    public static void main(String[] args) throws Exception {
        // Create the report
        FastReportBuilder drb = new FastReportBuilder();
        drb.addColumn("State", "state", String.class.getName(), 30)
            .addColumn("Amount", "amount", Float.class.getName(), 70)
            .setTitle("November 2004 sales report")
            .setSubtitle(MyUtils.getCurrentDate());
        DynamicReport dr = drb.build();

        // Generate the report
        DataSource ds = new JRBeanCollectionDataSource(TestRepositoryProducts.getDummyCollection());
        JasperPrint print = JasperFillManager.fillReport(DynamicJasperHelper.generateJasperReport(dr),
            new HashMap(), ds);
        JRPdfExporter exporter = new JRPdfExporter();
        exporter.setParameter(JRExporterParameter.OUTPUT_FILE, new File("fast_report.pdf"));
        exporter.setParameter(JRExporterParameter.JASPER_PRINT, print);
        exporter.exportReport();
    }
}

DynamicReportBuilder drb = new DynamicReportBuilder();
drb.addTitle("November 2004 sales report", titleStyle);
